const __pageData = JSON.parse('{"title":"Java NIO Selector 工程实践：事件循环、半包处理与连接治理","description":"","frontmatter":{"title":"Java NIO Selector 工程实践：事件循环、半包处理与连接治理","date":"2026-08-11T00:00:00.000Z","category":"后端开发","cover":"/covers/backend.svg","tags":["java","nio","selector","network","reactor"],"excerpt":"从五种 I/O 模型与 Selector 就绪通知出发，讲清 Channel、Buffer、SelectionKey 和事件循环，并用长度字段协议落实半包、粘包、写回压、跨线程唤醒与连接治理。"},"headers":[],"relativePath":"posts/java-nio-selector-engineering.md","filePath":"posts/java-nio-selector-engineering.md","lastUpdated":1786439465000}');
